// Process each user's preferences
const users = [];

for (const item of $input.all()) {
  const user = item.json;

  // Parse categories
  const categories = JSON.parse(user.subscribed_categories);

  // Sort by priority (highest first)
  categories.sort((a, b) => b.priority - a.priority);

  // Calculate weights for each category based on priority
  const totalPriority = categories.reduce((sum, cat) => sum + cat.priority, 0);

  categories.forEach(cat => {
    cat.weight = cat.priority / totalPriority;
  });

  users.push({
    userId: user.user_id,
    email: user.email,
    username: user.username,
    categories: categories
  });
}

return users.map(user => ({ json: user }));

// Analyze user's content consumption patterns
const user = $node['Process User Preferences'].json;
const readHistory = $input.all().map(item => item.json);

// Calculate content type preferences
const contentTypeCount = {};
readHistory.forEach(item => {
  contentTypeCount[item.content_type] = (contentTypeCount[item.content_type] || 0) + 1;
});

const totalRead = readHistory.length;
const contentTypePreferences = {};
Object.keys(contentTypeCount).forEach(type => {
  contentTypePreferences[type] = contentTypeCount[type] / totalRead;
});

// Get IDs of already read content to exclude
const readContentIds = readHistory.map(item => item.id);

// Calculate recency factor (more weight to recent reads)
const recentReads = readHistory.filter(item => {
  const daysSince = (Date.now() - new Date(item.interacted_at).getTime()) / (1000 * 60 * 60 * 24);
  return daysSince <= 7;
}).length;

const engagementScore = Math.min((recentReads / 7), 1); // Normalize to 0-1

return [{
  json: {
    ...user,
    contentTypePreferences,
    readContentIds,
    engagementScore,
    totalReadLast30Days: totalRead
  }
}];

// Organize recommendations by category and apply diversity
const user = $node['Analyze User Patterns'].json;
const allContent = $input.all().map(item => item.json);

// Group by category
const byCategory = {};
allContent.forEach(content => {
  const catSlug = content.category_slug;
  if (!byCategory[catSlug]) {
    byCategory[catSlug] = {
      categoryId: content.category_id,
      categoryName: content.category_name,
      categorySlug: catSlug,
      papers: [],
      videos: [],
      articles: []
    };
  }

  if (content.content_type === 'paper') {
    byCategory[catSlug].papers.push(content);
  } else if (content.content_type === 'video') {
    byCategory[catSlug].videos.push(content);
  } else {
    byCategory[catSlug].articles.push(content);
  }
});

// Sort categories by user priority
const sortedCategories = Object.keys(byCategory).sort((a, b) => {
  const catA = user.categories.find(c => c.category_slug === a);
  const catB = user.categories.find(c => c.category_slug === b);
  return (catB?.priority || 0) - (catA?.priority || 0);
});

// Build daily feed
const dailyFeed = {
  userId: user.userId,
  email: user.email,
  username: user.username,
  generatedAt: new Date().toISOString(),
  categories: []
};

let totalItems = 0;
const maxItemsPerUser = 20;

for (const catSlug of sortedCategories) {
  if (totalItems >= maxItemsPerUser) break;

  const cat = byCategory[catSlug];
  const userCat = user.categories.find(c => c.category_slug === catSlug);

  // Calculate how many items for this category based on priority
  const itemsForCategory = Math.max(
    2,
    Math.ceil(maxItemsPerUser * (userCat?.weight || 0.1))
  );

  const categoryFeed = {
    categoryId: cat.categoryId,
    categoryName: cat.categoryName,
    categorySlug: catSlug,
    priority: userCat?.priority || 5,
    content: []
  };

  // Add 1 paper if available
  if (cat.papers.length > 0) {
    categoryFeed.content.push(cat.papers[0]);
    totalItems++;
  }

  // Add videos
  const videosToAdd = Math.min(cat.videos.length, Math.floor(itemsForCategory * 0.4));
  for (let i = 0; i < videosToAdd && totalItems < maxItemsPerUser; i++) {
    categoryFeed.content.push(cat.videos[i]);
    totalItems++;
  }

  // Add articles
  const articlesNeeded = Math.min(
    cat.articles.length,
    itemsForCategory - categoryFeed.content.length
  );
  for (let i = 0; i < articlesNeeded && totalItems < maxItemsPerUser; i++) {
    categoryFeed.content.push(cat.articles[i]);
    totalItems++;
  }

  if (categoryFeed.content.length > 0) {
    dailyFeed.categories.push(categoryFeed);
  }
}

// Calculate feed stats
dailyFeed.stats = {
  totalItems,
  totalCategories: dailyFeed.categories.length,
  paperCount: allContent.filter(c => c.content_type === 'paper').length,
  videoCount: allContent.filter(c => c.content_type === 'video').length,
  articleCount: allContent.filter(c => c.content_type === 'article').length
};

return [{ json: dailyFeed }];

// Store recommendations in database
const feed = $input.item.json;
const contentItems = [];

feed.categories.forEach(cat => {
  cat.content.forEach((content, index) => {
    contentItems.push({
      userId: feed.userId,
      contentId: content.id,
      categoryId: cat.categoryId,
      recommendationScore: content.recommendation_score || 0,
      position: index + 1,
      categoryPosition: cat.content.length
    });
  });
});

return contentItems.map(item => ({ json: item }));

// Prepare email notification data
const feed = $node['Organize Daily Feed'].json;

// Format content for email
const emailContent = {
  to: feed.email,
  subject: `Your Daily Educational Feed - ${new Date().toLocaleDateString('en-US', { month: 'long', day: 'numeric', year: 'numeric' })}`,
  username: feed.username,
  totalItems: feed.stats.totalItems,
  categories: feed.categories.map(cat => ({
    name: cat.categoryName,
    items: cat.content.map(content => ({
      type: content.content_type,
      title: content.title,
      description: content.description.substring(0, 200) + '...',
      url: content.url,
      author: content.author,
      thumbnail: content.thumbnail_url,
      duration: content.duration ? Math.ceil(content.duration / 60) + ' min' : null,
      wordCount: content.word_count ? Math.ceil(content.word_count / 200) + ' min read' : null,
      publishedAt: new Date(content.published_at).toLocaleDateString()
    }))
  }))
};

return [{ json: emailContent }];

// Format summary for this user
const feed = $node['Organize Daily Feed'].json;
const recommendations = $('Save Recommendations').all();

return [{
  json: {
    userId: feed.userId,
    username: feed.username,
    email: feed.email,
    recommendationsGenerated: recommendations.length,
    totalItems: feed.stats.totalItems,
    categoriesIncluded: feed.stats.totalCategories,
    breakdown: {
      papers: feed.stats.paperCount,
      videos: feed.stats.videoCount,
      articles: feed.stats.articleCount
    }
  }
}];

// Create final execution summary
const allUsers = $input.all().map(item => item.json);

const totalUsers = allUsers.length;
const totalRecommendations = allUsers.reduce((sum, u) => sum + u.recommendationsGenerated, 0);
const totalPapers = allUsers.reduce((sum, u) => sum + u.breakdown.papers, 0);
const totalVideos = allUsers.reduce((sum, u) => sum + u.breakdown.videos, 0);
const totalArticles = allUsers.reduce((sum, u) => sum + u.breakdown.articles, 0);
const avgRecommendationsPerUser = totalRecommendations / totalUsers;

return [{
  json: {
    workflow: 'Daily Recommendation Engine',
    executedAt: new Date().toISOString(),
    stats: {
      totalUsersProcessed: totalUsers,
      totalRecommendationsGenerated: totalRecommendations,
      avgRecommendationsPerUser: Math.round(avgRecommendationsPerUser * 10) / 10,
      contentBreakdown: {
        papers: totalPapers,
        videos: totalVideos,
        articles: totalArticles
      },
      usersWithRecommendations: allUsers.filter(u => u.recommendationsGenerated > 0).length,
      usersWithoutContent: allUsers.filter(u => u.recommendationsGenerated === 0).length
    },
    success: true
  }
}];
